#include "live_reference_identity_registry.h"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8);if(argc!=2)return 2;std::ifstream f(argv[1],std::ios::binary);if(!f)throw std::runtime_error("missing oracle");auto word=[&](){uint32_t v=0;f.read(reinterpret_cast<char*>(&v),4);if(!f)throw std::runtime_error("short oracle");return v;};std::array<RecoveredPendingIdentityCandidate,24>identities{};for(unsigned h=1;h<24;++h)identities[h]={h%4,h%3,17,29};auto resolve=[&](uint32_t h)->const RecoveredPendingIdentityCandidate*{return h%5?&identities.at(h):nullptr;};unsigned cases=0;
 for(unsigned sequence=0;sequence<64;++sequence){RecoveredLiveIdentityRegistryCandidate registry(16);for(unsigned step=0;step<64;++step){uint32_t h=1+(step*13+sequence)%23;auto result=registry.insert(h,resolve);if(result!=word()||registry.find(identities[h],resolve)!=word())throw std::runtime_error("native live registry result mismatch");for(const auto&bucket:registry.buckets()){if(bucket.size()!=word())throw std::runtime_error("live count mismatch");for(auto value:bucket)if(value!=word())throw std::runtime_error("live handle mismatch");}++cases;}}
 if(f.peek()!=std::char_traits<char>::eof())throw std::runtime_error("trailing oracle");std::cout<<"native_live_identity_registry_matches="<<cases<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
